// Braintree hosted fields: the card data lives in Braintree iframes, the page only gets a nonce.
// The authorization is the client token generated by the server (GET /api/payments/config).
import braintree from "braintree-web";
import { HOSTED_FIELDS_OPTIONS } from "./hostedFields.js";

// adds the empty field keys to a tokenize() error, so the form can say "required" or "invalid"
const withEmptyKeys = (error, state) =>
    error?.details && state?.fields
        ? Object.assign(error, {
              details: { ...error.details, emptyFieldKeys: Object.keys(state.fields).filter(e => state.fields[e].isEmpty) }
          })
        : error;

const createHostedFields = async authorization => {
    const client = await braintree.client.create({ authorization });
    const fields = await braintree.hostedFields.create({ client, ...HOSTED_FIELDS_OPTIONS });
    const tokenize = async () => {
        try {
            return await fields.tokenize();
        } catch (error) {
            throw withEmptyKeys(error, fields.getState?.());
        }
    };
    return { tokenize };
};

export { createHostedFields };
